40	export class CloudConfig {
41	  private config: {
42	    appUrl: string;
43	    apiHost?: string;
44	    apiKey?: string;
45	    sharing?: boolean;
46	    currentOrganizationId?: string;
47	    currentTeamId?: string;
48	    teams?: {
49	      [organizationId: string]: {
50	        currentTeamId?: string;
51	        cache?: Array<{
52	          id: string;
53	          name: string;
54	          slug: string;
55	          lastFetched: string;
56	        }>;
57	      };
58	    };
