/**
 * Returns the team with the earliest `createdAt` date (the oldest team).
 */
function pickOldestTeam<T extends { createdAt: string }>(teams: T[]): T {
  return [...teams].sort(
    (a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime(),
  )[0];
}

/**
 * Finds a team by identifier using the priority: exact id, then case-insensitive
 * display name, then slug. The display-name match intentionally takes precedence
 * over a slug match when both exist.
 */
function findTeamByIdentifier(teams: LoginTeam[], identifier: string): LoginTeam | undefined {
  return (
    teams.find((t) => t.id === identifier) ||
    teams.find((t) => t.name.toLowerCase() === identifier.toLowerCase()) ||
    teams.find((t) => t.slug === identifier)
  );
}

/**
