 * the selection. When multiple teams exist and the environment is
 * non-interactive (or the user cancels interactive selection), the oldest team
 * is selected automatically rather than calling the cloud API.
 */
async function selectTeamForLogin(
  teams: LoginTeam[],
  organizationId: string,
): Promise<LoginTeam | undefined> {
  if (teams.length === 0) {
    return undefined;
  }

  if (teams.length === 1) {
    const team = teams[0];
    cloudConfig.setCurrentTeamId(team.id, organizationId);
