[metadata] {"filePath": "/workspace/repo/src/commands/auth.ts", "oldString": "export function authCommand(program: Command) {", "newString": "/**
 * Resolves the organization and team context for a login, persisting the
 * organization, cached teams, and current team selection. Nothing about the API
 * token itself is persisted here.
 *
 * @returns `true` when resolution succeeded and credentials may be persisted;
 *   `false` when resolution failed (e.g. an unknown `--org`), in which case
 *   `process.exitCode` has already been set and credentials must not be saved.
 * @throws Error when an explicitly requested team cannot be found.
 */
async function resolveOrgAndTeamForLogin(
  cmdObj: { org?: string; team?: string },
  allTeams: LoginTeam[],
  fallbackOrganizationId: string,
): Promise<boolean> {
  if (cmdObj.org) {
    // --org specified: restrict to teams within that organization.
    const orgTeams = allTeams.filter((t) => t.organizationId === cmdObj.org);

    if (orgTeams.length === 0) {
      const availableOrganizations = Array.from(
        new Set([fallbackOrganizationId, ...allTeams.map((t) => t.organizationId)]),
      );
      logger.error(
        `Authentication failed: Organization '${cmdObj.org}' not found in your accessible teams. Available organizations: ${availableOrganizations.join(', ')}`,
      );
      process.exitCode = 1;
      return false;
    }

    cloudConfig.setCurrentOrganization(cmdObj.org);
    cloudConfig.cacheTeams(orgTeams, cmdObj.org);

    if (cmdObj.team) {
      const selectedTeam = findTeamByIdentifier(orgTeams, cmdObj.team);
      if (!selectedTeam) {
        throw new Error(`Team '${cmdObj.team}' not found in organization '${cmdObj.org}'`);
      }
      cloudConfig.setCurrentTeamId(selectedTeam.id, cmdObj.org);
      logger.info(`Team: ${chalk.cyan(selectedTeam.name)}`);
    } else {
      await selectTeamForLogin(orgTeams, cmdObj.org);
    }
    return true;
  }

  if (cmdObj.team) {
    // --team without --org: search across all accessible organizations.
    const selectedTeam = findTeamByIdentifier(allTeams, cmdObj.team);
    if (!selectedTeam) {
      throw new Error(`Team '${cmdObj.team}' not found`);
    }
    const orgId = selectedTeam.organizationId;
    const orgTeams = allTeams.filter((t) => t.organizationId === orgId);
    cloudConfig.setCurrentOrganization(orgId);
    cloudConfig.cacheTeams(orgTeams, orgId);
    cloudConfig.setCurrentTeamId(selectedTeam.id, orgId);
    logger.info(`Team: ${chalk.cyan(selectedTeam.name)}`);
    return true;
  }

  // No flags: prefer the token's default organization.
  const defaultOrgTeams = allTeams.filter((t) => t.organizationId === fallbackOrganizationId);

  if (defaultOrgTeams.length > 0) {
    cloudConfig.setCurrentOrganization(fallbackOrganizationId);
    cloudConfig.cacheTeams(defaultOrgTeams, fallbackOrganizationId);
    await selectTeamForLogin(defaultOrgTeams, fallbackOrganizationId);
  } else if (allTeams.length > 0) {
    // Default organization has no teams, but others do: resolve to the
    // organization containing the oldest-created team.
    const resolvedOrgId = pickOldestTeam(allTeams).organizationId;
    const orgTeams = allTeams.filter((t) => t.organizationId === resolvedOrgId);
    cloudConfig.setCurrentOrganization(resolvedOrgId);
    cloudConfig.cacheTeams(orgTeams, resolvedOrgId);
    logger.info(`Organization: ${chalk.cyan(resolvedOrgId)}`);
    await selectTeamForLogin(orgTeams, resolvedOrgId);
  } else {
    // No teams at all.
    cloudConfig.setCurrentOrganization(fallbackOrganizationId);
    cloudConfig.cacheTeams([], fallbackOrganizationId);
  }
  return true;
}

